    createParticleEmitter(position, direction, size, spawnInterval, amount, velocity){
        let emitter = new ParticleEmitter(position, direction, size, spawnInterval, amount, velocity);
        this.particleEmitters.push(emitter);
        return emitter;
    }

    setPourAmount(value){
        this.pourAmount = Math.max(0, Math.min(1, value));
        this.bottle.angle = Math.PI / 2 - this.pourAmount * Math.PI * 1.05;
        this.updateBottleFromPour();
    }

    setBottleCenter(position){
        this.bottle.center = position.Cpy();
        this.updateBottleFromPour();
    }

    rotateBottle(deltaAngle){
        this.bottle.angle += deltaAngle;
        this.bottle.angle = Math.max(-Math.PI * 0.78, Math.min(Math.PI * 1.18, this.bottle.angle));
        this.updateBottleFromPour();
    }

    createGlass(){
        this.shapes = [];
        let g = this.glass;
        let wallColor = "rgba(185,225,255,0.72)";

        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let leftTop = new Vector2(-g.topWidth * 0.5, topY);
        let rightTop = new Vector2(g.topWidth * 0.5, topY);
        let leftBottom = new Vector2(-g.bottomWidth * 0.5, bottomY);
        let rightBottom = new Vector2(g.bottomWidth * 0.5, bottomY);

        this.leftGlassWall = this.createSegmentCollider(leftTop, leftBottom, g.wall, wallColor);
        this.rightGlassWall = this.createSegmentCollider(rightBottom, rightTop, g.wall, wallColor);
        this.glassBase = this.createSegmentCollider(leftBottom, rightBottom, g.wall * 1.25, wallColor);

        this.shapes.push(this.leftGlassWall);
        this.shapes.push(this.rightGlassWall);
        this.shapes.push(this.glassBase);
    }

    createSegmentCollider(localA, localB, thickness, color){
        let direction = Sub(localB, localA);
        direction.Normalize();
        let normal = direction.GetNormal();
        let half = thickness * 0.5;

        let vertices = [
            this.glassLocalToWorld(Add(localA, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, half))),
            this.glassLocalToWorld(Add(localA, Scale(normal, half)))
        ];

        let polygon = new Polygon(vertices, color);
        let center = this.glassLocalToWorld(Scale(Add(localA, localB), 0.5));
        if(!polygon.isPointInside(center)){
            vertices.reverse();
            polygon = new Polygon(vertices, color);
        }

        return polygon;
    }

    createOrientedBox(localCenter, width, height, color){
        let corners = [
            new Vector2(-width * 0.5, -height * 0.5),
            new Vector2(width * 0.5, -height * 0.5),
            new Vector2(width * 0.5, height * 0.5),
            new Vector2(-width * 0.5, height * 0.5)
        ];

        let vertices = [];
        for(let i=0; i<corners.length; i++){
            vertices.push(this.glassLocalToWorld(Add(localCenter, corners[i])));
        }

        return new Polygon(vertices, color);
    }

    glassLocalToWorld(local){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        return new Vector2(
            this.glass.center.x + local.x * c - local.y * s,
            this.glass.center.y + local.x * s + local.y * c
