    }

    worldToGlassLocal(world){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        let dx = world.x - this.glass.center.x;
        let dy = world.y - this.glass.center.y;
        return new Vector2(dx * c + dy * s, -dx * s + dy * c);
    }

