    }

    updateBottleFromPour(){
        let totalLength = 330;
        let axis = new Vector2(Math.cos(this.bottle.angle), Math.sin(this.bottle.angle));
        let mouth = Sub(this.bottle.center, Scale(axis, totalLength * 0.5));
        let mouthOut = Scale(axis, -1);
        let downward = Math.max(0, mouthOut.y);
        let tiltFlow = Math.max(0, (downward - 0.16) / 0.78);
        tiltFlow = Math.min(1, tiltFlow);

        let pourDir = Add(Scale(mouthOut, 1.35), new Vector2(0, 0.72));
        pourDir.Normalize();

        this.bottle.mouth = mouth;
        this.bottle.axis = axis;
        this.bottle.pourDir = pourDir;
        this.pourAmount = this.bottleVolumeL <= 0 ? 0 : this.smoothStep(tiltFlow);

        this.emitter.position = mouth;
        this.emitter.direction = pourDir;
        this.emitter.flowScale = this.pourAmount;

