        for(let i=1; i < this.vertices.length;i++){
            DrawUtils.drawLine(this.vertices[i-1], this.vertices[i], this.color,3);
        }
        DrawUtils.drawLine(this.vertices[this.vertices.length-1], this.vertices[0], this.color,3);
    }
